UPDATE quiz_questions SET question_ru = 'Какой ролью снискала большую славу Сора Эшонтураева в 1935 году?', options_ru = '["Дездемоны", "Офелии", "Джамили", "Катерины"]'::jsonb, explanation_ru = 'В 1935 году она обрела славу, исполнив роль Офелии в трагедии Шекспира «Гамлет». А роль Дездемоны она сыграла позже, в спектакле «Отелло» 1941 года.' WHERE id = 2661;
UPDATE quiz_questions SET question_ru = 'В каком году Соре Эшонтураевой было присвоено звание народной артистки Узбекистана?', options_ru = '["1927", "1937", "1941", "1949"]'::jsonb, explanation_ru = 'Звание народной артистки Узбекистана было присвоено ей в 1937 году. А в 1927 году она окончила узбекскую драматическую студию в Москве и начала работать в театре Хамзы.' WHERE id = 2662;
UPDATE quiz_questions SET question_ru = 'Как назывался поэтический сборник Тавалло, напечатанный в 1916 году?', options_ru = '["«Отцеубийца»", "«Равнак уль-ислам»", "«Садои Туркистон»", "«Муштум»"]'::jsonb, explanation_ru = 'Единственный поэтический сборник, вышедший при жизни Тавалло, — «Равнак уль-ислам» 1916 года, в него вошло около 70 стихотворений. «Отцеубийца» — драма, поставленная в ту пору на сцене, «Садои Туркистон» — газета, «Муштум» — сатирический журнал.' WHERE id = 2663;
UPDATE quiz_questions SET question_ru = 'Каковы настоящие имя и фамилия Тавалло?', options_ru = '["Абдулла Авлони", "Мунавваркари Абдурашидханов", "Тулаган Ходжамьяров", "Убайдуллахан Асатуллаходжаев"]'::jsonb, explanation_ru = '«Тавалло» — литературный псевдоним поэта, а настоящее имя — Тулаган Ходжамьяров. Он родился в 1883 году в Кукчинской даха Ташкента. А Авлони и Мунавваркари были его друзьями-соратниками.' WHERE id = 2664;
