UPDATE quiz_questions SET question_ru = 'Соратником какого правителя стал позже Тимур Малик, продолжив борьбу против монголов?', options_ru = '["Амира Темура", "Махмуда Газневи", "Джалалиддина Мангуберди", "Захириддина Бабура"]'::jsonb, explanation_ru = 'В рассказе говорится, что Тимур Малик, пройдя трудный путь, присоединился к Джалалиддину Мангуберди, сражавшемуся с монголами на иранской земле.' WHERE id = 2666;
UPDATE quiz_questions SET question_ru = 'Какую награду получил Тагай Мурад за роман «Поля, оставшиеся от отца»?', options_ru = '["Государственную премию имени Алишера Навои", "Государственную премию имени Абдуллы Кадыри", "Премию имени Зульфии", "Премию имени Низами"]'::jsonb, explanation_ru = 'За написанный в 1993 году роман «Поля, оставшиеся от отца» Тагай Мурад удостоился в 1994 году Государственной премии имени Абдуллы Кадыри.' WHERE id = 2667;
UPDATE quiz_questions SET question_ru = 'В каком году написана повесть «Вечер, когда заржал конь»?', options_ru = '["В 1976 году", "В 1979 году", "В 1985 году", "В 1993 году"]'::jsonb, explanation_ru = 'Тагай Мурад написал повесть «Вечер, когда заржал конь» в 1979 году. А в 1976 году была издана его первая повесть «Звёзды горят вечно».' WHERE id = 2668;
